export function attributeKey(value){return String(value||'').normalize('NFKC').toLowerCase().replace(/[^\p{L}\p{N}]/gu,'');}
export function matchAttributes(meta,profile){const fields=[],seen=new Set(),unmatched=[];for(const attribute of profile.attributes){const key=attributeKey(attribute);const matches=(meta.fields||[]).filter(field=>attributeKey(field.name)===key||attributeKey(field.alias)===key);if(!matches.length)unmatched.push(attribute);for(const field of matches)if(!seen.has(field.name)){seen.add(field.name);fields.push(field);}}return {fields,unmatched};}
export function visibleFields(meta){if(!Array.isArray(meta?.__allowedFields))return meta?.fields||[];const byName=new Map((meta.fields||[]).map(f=>[f.name,f]));return meta.__allowedFields.map(name=>byName.get(name)).filter(Boolean);}
export async function loadAttributeProfiles(){const response=await fetch(new URL('./attribute-profiles.json?v=20261015-template',import.meta.url),{cache:'no-cache'});if(!response.ok)throw Error('The workbook attribute filter could not be loaded.');const data=await response.json();if(!Array.isArray(data.profiles)||!data.profiles.length)throw Error('Workbook attribute groups are missing.');return data;}
